        p_manager_emp_id IN NUMBER
    ) RETURN t_emp_id_table IS
        v_result t_emp_id_table;
        v_idx    BINARY_INTEGER := 0;
    BEGIN
        FOR r IN (
            SELECT EMP_ID
            FROM EMPLOYEES
            WHERE MANAGER_EMP_ID = p_manager_emp_id
            AND EMPLOYMENT_STATUS = 'ACTIVE'
            ORDER BY LAST_NAME, FIRST_NAME
