            RAISE_APPLICATION_ERROR(-20212, 'No business days in the selected range');
        END IF;

        -- Check for overlapping leave
        IF check_leave_overlap(p_emp_id, p_start_date, p_end_date) THEN
            RAISE_APPLICATION_ERROR(-20202,
