    PROCEDURE get_pending_requests(
        p_cursor        OUT t_leave_cursor,
        p_approver_id   IN NUMBER
    );

    PROCEDURE get_team_calendar(
        p_cursor        OUT t_leave_cursor,
        p_manager_id    IN NUMBER,
        p_start_date    IN DATE

