        'STATUS_CHANGE',
        NVL(:NEW.MODIFIED_BY, USER),
        '{"status":"' || :OLD.STATUS || '"}',
        '{"status":"' || :NEW.STATUS || '"}'
    );
END TRG_LEAVE_REQUEST_AUDIT;
/

