/

CREATE OR REPLACE TRIGGER HRMS.TRG_EMP_BEFORE_INSERT
BEFORE INSERT ON HRMS.EMPLOYEES
FOR EACH ROW
BEGIN
    -- Set audit columns
    IF :NEW.CREATED_BY IS NULL THEN
        :NEW.CREATED_BY := USER;
    END IF;
    IF :NEW.CREATED_DATE IS NULL THEN
        :NEW.CREATED_DATE := SYSDATE;
    END IF;

    -- Default active flag
    IF :NEW.ACTIVE_FLAG IS NULL THEN
        :NEW.ACTIVE_FLAG := 'Y';
    END IF;

    -- Default employment status
    IF :NEW.EMPLOYMENT_STATUS IS NULL THEN
        :NEW.EMPLOYMENT_STATUS := 'ACTIVE';
    END IF;

    -- Validate hire date not too far in the future
    IF :NEW.HIRE_DATE > SYSDATE + 180 THEN
        RAISE_APPLICATION_ERROR(-20501,
            'Hire date cannot be more than 180 days in the future');
    END IF;

    -- Validate email uniqueness (also enforced by unique constraint, but
    -- this trigger provides a better error message)
    DECLARE
        v_count NUMBER;
    BEGIN
        SELECT COUNT(*) INTO v_count
        FROM EMPLOYEES
        WHERE UPPER(EMAIL) = UPPER(:NEW.EMAIL)
        AND ACTIVE_FLAG = 'Y';

        IF v_count > 0 THEN
            RAISE_APPLICATION_ERROR(-20502,
                'Email address already in use: ' || :NEW.EMAIL);
        END IF;
    END;
END TRG_EMP_BEFORE_INSERT;
/

-- -----------------------------------------------------------------------
-- TRG_EMP_BEFORE_UPDATE
-- Sets modification audit columns and validates state transitions
-- -----------------------------------------------------------------------
CREATE OR REPLACE TRIGGER HRMS.TRG_EMP_BEFORE_UPDATE
BEFORE UPDATE ON HRMS.EMPLOYEES
FOR EACH ROW
BEGIN
    :NEW.MODIFIED_BY := NVL(:NEW.MODIFIED_BY, USER);
    :NEW.MODIFIED_DATE := SYSDATE;

    -- Prevent reactivation of terminated employees via direct UPDATE
    -- (should go through PKG_EMPLOYEE.rehire_employee instead)
    IF :OLD.EMPLOYMENT_STATUS = 'TERMINATED' AND :NEW.EMPLOYMENT_STATUS = 'ACTIVE' THEN
        RAISE_APPLICATION_ERROR(-20503,
            'Cannot directly reactivate a terminated employee. Use the rehire process.');
    END IF;

    -- Log status changes to history
    IF :OLD.EMPLOYMENT_STATUS != :NEW.EMPLOYMENT_STATUS THEN
        INSERT INTO EMPLOYEE_HISTORY (
            HISTORY_ID, EMP_ID, CHANGE_TYPE, CHANGE_DATE,
            OLD_VALUE, NEW_VALUE, CHANGED_BY, CHANGE_REASON
        ) VALUES (
            SEQ_EMP_HISTORY.NEXTVAL, :NEW.EMP_ID, 'STATUS_CHANGE', SYSDATE,
            :OLD.EMPLOYMENT_STATUS, :NEW.EMPLOYMENT_STATUS,
            NVL(:NEW.MODIFIED_BY, USER), 'Triggered by status update'
        );
    END IF;

    -- Log department transfers
    IF NVL(:OLD.DEPT_ID, -1) != NVL(:NEW.DEPT_ID, -1) THEN
        INSERT INTO EMPLOYEE_HISTORY (
            HISTORY_ID, EMP_ID, CHANGE_TYPE, CHANGE_DATE,
            OLD_VALUE, NEW_VALUE, CHANGED_BY, CHANGE_REASON
        ) VALUES (
            SEQ_EMP_HISTORY.NEXTVAL, :NEW.EMP_ID, 'DEPARTMENT_CHANGE', SYSDATE,
            TO_CHAR(:OLD.DEPT_ID), TO_CHAR(:NEW.DEPT_ID),
            NVL(:NEW.MODIFIED_BY, USER), 'Department transfer'
        );
    END IF;

    -- Log job changes
    IF NVL(:OLD.JOB_ID, -1) != NVL(:NEW.JOB_ID, -1) THEN
        INSERT INTO EMPLOYEE_HISTORY (
            HISTORY_ID, EMP_ID, CHANGE_TYPE, CHANGE_DATE,
            OLD_VALUE, NEW_VALUE, CHANGED_BY, CHANGE_REASON
        ) VALUES (
            SEQ_EMP_HISTORY.NEXTVAL, :NEW.EMP_ID, 'JOB_CHANGE', SYSDATE,
            TO_CHAR(:OLD.JOB_ID), TO_CHAR(:NEW.JOB_ID),
            NVL(:NEW.MODIFIED_BY, USER), 'Job title change'
        );
    END IF;
END TRG_EMP_BEFORE_UPDATE;
/

-- -----------------------------------------------------------------------
-- TRG_EMP_AFTER_DELETE
-- Soft delete: instead of actual deletion, marks record as inactive
-- NOTE: This trigger converts DELETE into an UPDATE, which is confusing
-- and a known maintenance issue
-- -----------------------------------------------------------------------
CREATE OR REPLACE TRIGGER HRMS.TRG_EMP_INSTEAD_OF_DELETE
BEFORE DELETE ON HRMS.EMPLOYEES
FOR E

DECLARE
    v_session_id NUMBER;
BEGIN
    -- Validate session
    v_session_id := TO_NUMBER(GET_APPLICATION_PROPERTY(USERNAME));
    IF NOT PKG_SECURITY.is_session_valid(v_session_id) THEN
        MESSAGE('Session expired. Please log in again.');
        RAISE FORM_TRIGGER_FAILURE;
    END IF;

    -- Set window title
    SET_WINDOW_PROPERTY(FORMS_MDI_WINDOW, TITLE,
        'HRMS - Employee Maintenance [' || :GLOBAL.current_user || ']');

    -- Restrict based on permissions
    IF NOT PKG_SECURITY.has_permission(:GLOBAL.current_emp_id, 'EMPLOYEE', 'EDIT') THEN
        SET_BLOCK_PROPERTY('EMPLOYEE', INSERT_ALLOWED, PROPERTY_FALSE);
        SET_BLOCK_PROPERTY('EMPLOYEE', UPDATE_ALLOWED, PROPERTY_FALSE);
        SET_BLOCK_PROPERTY('EMPLOYEE', DELETE_ALLOWED, PROPERTY_FALSE);
    END IF;

    -- Default query to active employees
    SET_BLOCK_PROPERTY('EMPLOYEE', DEFAULT_WHERE,
        'EMPLOYMENT_STATUS = ''ACTIVE'' AND ACTIVE_FLAG = ''Y''');

    -- Initialize LOVs
    POPULATE_GROUP('RG_DEPARTMENTS');
    POPULATE_GROUP('RG_JOB_TITLES');
    POPULATE_GROUP('RG_LOCATIONS');

    GO_BLOCK('EMPLOYEE');
    EXECUTE_QUERY;
END;

DECLARE
    v_errcode NUMBER := ERROR_CODE;
    v_errtype VARCHAR2(3) := ERROR_TYPE;
    v_errmsg  VARCHAR2(200) := ERROR_TEXT;
BEGIN
    IF v_errcode = 40202 THEN
        -- "Field is protected against update"
        NULL; -- Suppress
    ELSIF v_errcode = 40401 THEN
        -- "No changes to save"
        MESSAGE('No changes to save.');
    ELSIF v_errcode = 40501 THEN
        -- "Oracle error: unable to reserve record"
        MESSAGE('Record is locked by another user. Please try again.');
    ELSE
        MESSAGE(v_errtype || '-' || TO_CHAR(v_errcode) || ': ' || v_errmsg);
        RAISE FORM_TRIGGER_FAILURE;
    END IF;
END;

BEGIN
    IF :SYSTEM.FORM_STATUS = 'CHANGED' THEN
        IF SHOW_ALERT('ALT_CONFIRM_EXIT') = ALERT_BUTTON1 THEN
            COMMIT_FORM;
        ELSIF SHOW_ALERT('ALT_CONFIRM_EXIT') = ALERT_BUTTON2 THEN
            CLEAR_FORM(NO_VALIDATE);
        ELSE
            RAISE FORM_TRIGGER_FAILURE;
        END IF;
    END IF;
    EXIT_FORM;
END;

BEGIN
    :EMPLOYEE.EMP_ID := SEQ_EMPLOYEE.NEXTVAL;
    :EMPLOYEE.EMP_NUMBER := PKG_EMPLOYEE.generate_emp_number;
    :EMPLOYEE.ACTIVE_FLAG := 'Y';
    :EMPLOYEE.EMPLOYMENT_STATUS := 'ACTIVE';
    :EMPLOYEE.CREATED_BY := :GLOBAL.current_user;
    :EMPLOYEE.CREATED_DATE := SYSDATE;
END;

BEGIN
    :EMPLOYEE.MODIFIED_BY := :GLOBAL.current_user;
    :EMPLOYEE.MODIFIED_DATE := SYSDATE;
END;

BEGIN
    -- Populate display items
    BEGIN
        SELECT DEPT_NAME INTO :EMPLOYEE.DEPT_NAME_DISP
        FROM DEPARTMENTS WHERE DEPT_ID = :EMPLOYEE.DEPT_ID;
    EXCEPTION WHEN NO_DATA_FOUND THEN :EMPLOYEE.DEPT_NAME_DISP := NULL;
    END;

    BEGIN
        SELECT JOB_TITLE INTO :EMPLOYEE.JOB_TITLE_DISP
        FROM JOB_TITLES WHERE JOB_ID = :EMPLOYEE.JOB_ID;
    EXCEPTION WHEN NO_DATA_FOUND THEN :EMPLOYEE.JOB_TITLE_DISP := NULL;
    END;

    BEGIN
        SELECT FIRST_NAME || ' ' || LAST_NAME INTO :EMPLOYEE.MANAGER_NAME_DISP
        FROM EMPLOYEES WHERE EMP_ID = :EMPLOYEE.MANAGER_EMP_ID;
    EXCEPTION WHEN NO_DATA_FOUND THEN :EMPLOYEE.MANAGER_NAME_DISP := NULL;
    END;
END;

DECLARE
    v_item VARCHAR2(60) := :SYSTEM.TRIGGER_ITEM;
BEGIN
    IF v_item = 'EMPLOYEE.EMAIL' THEN
        IF :EMPLOYEE.EMAIL IS NOT NULL
           AND NOT PKG_VALIDATION.validate_email_format(:EMPLOYEE.EMAIL) THEN
            MESSAGE('Invalid email format');
            RAISE FORM_TRIGGER_FAILURE;
        END IF;

    ELSIF v_item = 'EMPLOYEE.HIRE_DATE' THEN
        IF :EMPLOYEE.HIRE_DATE > SYSDATE + 90 THEN
            MESSAGE('Hire date cannot be more than 90 days in the future');
            RAISE FORM_TRIGGER_FAILURE;
        END IF;

    ELSIF v_item = 'EMPLOYEE.DEPT_ID' THEN
        -- Auto-populate department name
        BEGIN
            SELECT DEPT_NAME INTO :EMPLOYEE.DEPT_NAME_DISP
            FROM DEPARTMENTS
            WHERE DEPT_ID = :EMPLOYEE.DEPT_ID AND ACTIVE_FLAG = 'Y';
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                MESSAGE('Invalid department');
                RAISE FORM_TRIGGER_FAILURE;
        END;

    ELSIF v_item = 'EMPLOYEE.JOB_ID' THEN
        BEGIN
            SELECT JOB_TITLE INTO :EMPLOYEE.JOB_TITLE_DISP
            FROM JOB_TITLES
            WHERE JOB_ID = :EMPLOYEE.JOB_ID AND ACTIVE_FLAG = 'Y';
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                MESSAGE('Invalid job title');
                RAISE FORM_TRIGGER_FAILURE;
        END;
    END IF;
END;

BEGIN
    -- Session validation
    IF NOT PKG_SECURITY.is_session_valid(
        TO_NUMBER(GET_APPLICATION_PROPERTY(USERNAME))) THEN
        MESSAGE('Session expired.');
        RAISE FORM_TRIGGER_FAILURE;
    END IF;

    SET_WINDOW_PROPERTY(FORMS_MDI_WINDOW, TITLE,
        'HRMS - Leave Management [' || :GLOBAL.current_user || ']');

    -- Show current user's leave requests by default
    SET_BLOCK_PROPERTY('LEAVE_REQUEST', DEFAULT_WHERE,
        'EMP_ID = ' || :GLOBAL.current_emp_id || ' ORDER BY CREATED_DATE DESC');

    -- Populate leave type LOV
    POPULATE_GROUP('RG_LEAVE_TYPES');

    GO_BLOCK('LEAVE_REQUEST');
    EXECUTE_QUERY;

    -- Show leave balances
    GO_BLOCK('LEAVE_BALANCE');
    EXECUTE_QUERY;
    GO_BLOCK('LEAVE_REQUEST');
END;

BEGIN
    IF :LEAVE_REQUEST.STATUS NOT IN ('PENDING', 'APPROVED') THEN
        MESSAGE('Only pending or approved requests can be cancelled.');
        RAISE FORM_TRIGGER_FAILURE;
    END IF;

    IF SHOW_ALERT('ALT_CONFIRM_CANCEL') = ALERT_BUTTON1 THEN
        PKG_LEAVE.cancel_leave_request(
            :LEAVE_REQUEST.REQUEST_ID, 'Cancelled by employee', :GLOBAL.current_user);
        MESSAGE('Leave request cancelled.');
        EXECUTE_QUERY;
    END IF;
END;

BEGIN
    SELECT lt.LEAVE_TYPE_NAME INTO :LEAVE_REQUEST.LEAVE_TYPE_NAME_DISP
    FROM LEAVE_TYPES lt
    JOIN LEAVE_REQUESTS lr ON lt.LEAVE_TYPE_ID = lr.LEAVE_TYPE_ID
    WHERE lr.REQUEST_ID = :LEAVE_REQUEST.REQUEST_ID;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        :LEAVE_REQUEST.LEAVE_TYPE_NAME_DISP := 'Unknown';
END;

DECLARE
    v_request_id NUMBER;
BEGIN
    -- Validate required fields
    IF :NEW_REQUEST.NR_LEAVE_TYPE_ID IS NULL THEN
        MESSAGE('Please select a leave type.');
        RAISE FORM_TRIGGER_FAILURE;
    END IF;
    IF :NEW_REQUEST.NR_START_DATE IS NULL THEN
        MESSAGE('Please enter a start date.');
        RAISE FORM_TRIGGER_FAILURE;
    END IF;
    IF :NEW_REQUEST.NR_END_DATE IS NULL THEN
        MESSAGE('Please enter an end date.');
        RAISE FORM_TRIGGER_FAILURE;
    END IF;

    v_request_id := PKG_LEAVE.submit_leave_request(
        p_emp_id        => :GLOBAL.current_emp_id,
        p_leave_type_id => :NEW_REQUEST.NR_LEAVE_TYPE_ID,
        p_start_date    => :NEW_REQUEST.NR_START_DATE,
        p_end_date      => :NEW_REQUEST.NR_END_DATE,
        p_half_day_flag => NVL(:NEW_REQUEST.NR_HALF_DAY, 'N'),
        p_reason        => :NEW_REQUEST.NR_REASON,
        p_user          => :GLOBAL.current_user
    );

    MESSAGE('Leave request #' || v_request_id || ' submitted successfully.');
    CLEAR_BLOCK(NO_VALIDATE);

    -- Refresh requests list
    GO_BLOCK('LEAVE_REQUEST');
    EXECUTE_QUERY;
END;

BEGIN
    SET_WINDOW_PROPERTY(FORMS_MDI_WINDOW, TITLE, 'HRMS Login');
    SET_WINDOW_PROPERTY('WIN_LOGIN', WINDOW_STATE, NORMAL);
    GO_ITEM('LOGIN.USERNAME');
END;

DECLARE
    v_session_id NUMBER;
BEGIN
    :LOGIN.ERROR_MSG := NULL;

    IF :LOGIN.USERNAME IS NULL OR :LOGIN.PASSWORD IS NULL THEN
        :LOGIN.ERROR_MSG := 'Please enter username and password.';
        RAISE FORM_TRIGGER_FAILURE;
    END IF;

    BEGIN
        v_session_id := PKG_SECURITY.authenticate(
            :LOGIN.USERNAME,
            :LOGIN.PASSWORD,
            GET_APPLICATION_PROPERTY(CLIENT_HOST)
        );

        -- Store session info in global variables
        :GLOBAL.session_id := TO_CHAR(v_session_id);
        :GLOBAL.current_user := :LOGIN.USERNAME;

        -- Get employee details
        SELECT EMP_ID INTO :GLOBAL.current_emp_id
        FROM EMPLOYEES
        WHERE UPPER(EMAIL) = UPPER(:LOGIN.USERNAME)
        AND EMPLOYMENT_STATUS = 'ACTIVE'
        AND ROWNUM = 1;

        -- Open main menu
        OPEN_FORM('HRMS_MENU', ACTIVATE, SESSION);

    EXCEPTION
        WHEN OTHERS THEN
            :LOGIN.ERROR_MSG := 'Invalid username or password.';
            :LOGIN.PASSWORD := NULL;
            GO_ITEM('LOGIN.PASSWORD');
            RAISE FORM_TRIGGER_FAILURE;
    END;
END;

BEGIN
    IF :SYSTEM.CURSOR_ITEM = 'LOGIN.PASSWORD' THEN
        DO_KEY('WHEN-BUTTON-PRESSED');
